SET local check_function_bodies = off;

CREATE OR REPLACE FUNCTION private.claim_notification_pushes (
  receipts boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  jobs jsonb;
begin
  with candidates as (
    select d.id from private.notification_push_deliveries d
    where d.state = case when receipts then 'receipt' else 'pending' end
      and d.available_at <= now() and (d.leased_until is null or d.leased_until <= now())
    order by d.available_at, d.id limit 100 for update skip locked
  ), claimed as (
    update private.notification_push_deliveries d
    set lease_id = gen_random_uuid(), leased_until = now() + interval '5 minutes', attempts = attempts + 1
    from candidates c where d.id = c.id returning d.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', d.id::text, 'lease_id', d.lease_id, 'ticket_id', d.ticket_id,
    'allowed', private.push_notification_allowed(n.id, t.id),
    'expired', n.created_at <= now() - interval '24 hours',
    'token', t.token, 'recipient_id', n.recipient_id, 'post_id', p.id::text, 'post_type', p.type,
    'comment_id', n.comment_id::text,
    'title', case when n.type = 'vote_ended' then '투표가 종료됐어요.' else n.title end,
    -- NOTI-010 답글 Push는 '{닉네임}: ' 뒤 답글 본문을 42자까지 보여 준다. 댓글 Push(NOTI-004)는 자르지 않는다.
    'body', case when n.type = 'vote_ended' then '내 투표 결과를 확인해 보세요.'
      when n.event_key like 'reply:%' and position(': ' in n.body) > 0
        then left(n.body, position(': ' in n.body) + 1) ||
          private.notification_excerpt(substr(n.body, position(': ' in n.body) + 2), 42)
      else n.body end
  ) order by d.id), '[]'::jsonb) into jobs
  from claimed d join private.notifications n on n.id = d.notification_id
  join private.posts p on p.id = n.post_id join public.push_tokens t on t.id = d.token_id;
  return jobs;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_app_notifications (
  after_created_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  after_key        text                     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare viewer_id uuid := private.notification_viewer();
begin
  if (after_created_at is null)<>(after_key is null) or
    (after_key is not null and after_key !~ '^(notice:)?[1-9][0-9]{0,18}$') then
    raise exception 'invalid_notification_cursor' using errcode='22023';
  end if;
  return (with entries as (
    select n.id::text as key,n.created_at,jsonb_build_object(
      'id',n.id::text,'title',n.title,'body',n.body,'created_at',n.created_at,
      'post_id',p.id::text,'post_type',p.type,'comment_id',n.comment_id::text,'is_post_available',
      p.deleted_at is null and p.hidden_at is null and private.community_author_visible(p.author_id)
      and private.community_content_visible('post',p.id)) as data
    from private.notifications n join private.posts p on p.id=n.post_id
    where n.recipient_id=viewer_id and n.created_at>now()-interval '30 days'
      and (n.actor_id is null or private.notification_actor_visible(viewer_id,n.actor_id))
    union all
    select 'notice:'||p.id::text,p.created_at,jsonb_build_object(
      'id','notice:'||p.id::text,'title',p.notice_title,
      'body',coalesce(nullif(p.notice_inbox_body,''),p.content),'created_at',p.created_at,
      'post_id',p.id::text,'post_type','notice','is_post_available',true)
    from private.posts p where p.notice_title is not null and p.deleted_at is null and p.hidden_at is null
      and p.created_at>now()-interval '30 days'
      and private.community_author_visible(p.author_id) and private.community_content_visible('post',p.id)
  ) select coalesce(jsonb_agg(e.data order by e.created_at desc,e.key collate "C" desc),'[]')
    from (select * from entries where after_created_at is null or
      (created_at,key collate "C")<(after_created_at,after_key collate "C")
      order by created_at desc,key collate "C" desc limit 20) e);
end;
$function$;

CREATE OR REPLACE FUNCTION private.notification_excerpt (
  value      text,
  max_length integer
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case when char_length(private.notification_text(value)) > max_length
    then rtrim(regexp_replace(left(private.notification_text(value), max_length),
      '[\u00A9\u00AE\u203C\u2049\u2122\u2139\u2194-\u21AA\u231A-\u23FF\u24C2\u25AA-\u27BF\u2934\u2935\u2B05-\u2B55\u3030\u303D\u3297\u3299\uFE0F\u200D\U0001F000-\U0001FAFF\U000E0020-\U000E007F]+$', '')) || '...'
    else private.notification_text(value) end;
$function$;

CREATE OR REPLACE FUNCTION private.notify_comment_liked()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.comments%rowtype;
begin
  select * into target from private.comments where id = new.comment_id;
  if target.author_id is null or target.deleted_at is not null or target.hidden_at is not null or
     exists(select 1 from private.posts p where p.id = target.post_id and (p.deleted_at is not null or p.hidden_at is not null)) or
     (select count(*) from private.comment_likes l where l.comment_id = new.comment_id) <> 10 then
    return new;
  end if;
  insert into private.comment_like_notifications(comment_id) values (target.id) on conflict do nothing;
  if not found then return new; end if;
  insert into private.notifications(recipient_id, type, post_id, comment_id, title, body, event_key)
  values (target.author_id, 'comment_liked', target.post_id, target.id, '내 댓글에 10개 이상의 좋아요가 달렸어요.',
          '''' || private.notification_excerpt(target.content, 20) || ''' 댓글에 달린 좋아요를 확인해 보세요.',
          'commentlike10:' || target.id)
  on conflict (event_key) do nothing;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.notify_post_liked()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
begin
  select * into target from private.posts where id = new.post_id;
  if target.notice_title is not null or target.type <> 'post' or target.deleted_at is not null or
     target.hidden_at is not null or (select count(*) from private.post_likes l where l.post_id = new.post_id) <> 10 then
    return new;
  end if;
  insert into private.post_like_notifications(post_id) values (target.id) on conflict do nothing;
  if not found then return new; end if;
  -- 목록과 Push 본문은 글 앞 20자에 안내 문장을 붙인다.
  insert into private.notifications(recipient_id, type, post_id, title, body, event_key)
  values (target.author_id, 'post_liked', target.id, '내 게시글에 10개 이상의 좋아요가 달렸어요.',
          '''' || private.notification_excerpt(target.content, 20) || ''' 게시글에 달린 좋아요를 확인해 보세요.',
          'like10:' || target.id)
  on conflict (event_key) do nothing;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.push_notification_allowed (
  notification_id bigint,
  token_id        bigint
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from private.notifications n
    join private.posts p on p.id = n.post_id
    join public.profiles u on u.id = n.recipient_id
    join public.push_tokens t on t.id = token_id and t.user_id = n.recipient_id
    left join private.notification_settings s on s.user_id = n.recipient_id
    where n.id = notification_id and n.created_at > now() - interval '24 hours'
      and u.status <> 'suspended' and coalesce(s.push_enabled, true)
      and p.deleted_at is null and p.hidden_at is null
      and (n.comment_id is null or exists (
        select 1 from private.comments c where c.id = n.comment_id and c.deleted_at is null and c.hidden_at is null
      ))
      and (n.type <> 'post_commented' or exists (
        select 1 from private.comments c
        where c.post_id = n.post_id and n.event_key in ('comment:' || c.id, 'reply:' || c.id)
          and c.deleted_at is null
      ))
      and (n.actor_id is null or private.notification_actor_visible(n.recipient_id, n.actor_id))
  );
$function$;

ALTER TABLE "private"."comment_like_notifications"
  ADD CONSTRAINT "comment_like_notifications_comment_id_fkey" FOREIGN KEY (comment_id) REFERENCES private.comments(id) ON DELETE CASCADE;

ALTER TABLE "private"."notifications"
  ADD CONSTRAINT "notifications_comment_id_fkey" FOREIGN KEY (comment_id) REFERENCES private.comments(id) ON DELETE CASCADE;

CREATE INDEX notifications_comment_idx ON private.notifications USING btree (comment_id)
  WHERE (comment_id IS NOT NULL);

CREATE TRIGGER comment_likes_notify_author
  AFTER INSERT ON private.comment_likes
  FOR EACH ROW
  EXECUTE FUNCTION private.notify_comment_liked();

REVOKE ALL ON FUNCTION "private"."notification_excerpt"(text, integer) FROM PUBLIC;

REVOKE ALL ON FUNCTION "private"."notify_comment_liked"() FROM PUBLIC;
